# CODEFORGE GROQ RELIABILITY + LOCAL PRACTICE PATCH 005
# Fixes intermittent AI usefulness by:
# - serving explicit topic problem recommendations locally from CodeForge DB
# - caching identical AI decisions for 5 minutes
# - reducing conversation payload size
# - using medium reasoning for normal coaching and high reasoning for coding/debugging
# - using strict Groq JSON schema output
# - preventing unsupported reminder/profile-update claims
# - preserving Groq -> Groq fallback -> Gemini -> local fallback
#
# Run from either the CodeForge project root OR backend folder.
# This patch does NOT touch or print any API key.

$ErrorActionPreference = "Stop"

$Here = (Get-Location).Path
if (Test-Path (Join-Path $Here "app\Services\AiAssistantService.php")) {
    $Backend = $Here
} elseif (Test-Path (Join-Path $Here "backend\app\Services\AiAssistantService.php")) {
    $Backend = Join-Path $Here "backend"
} else {
    throw "CodeForge backend not found. Run this script from the project root or backend folder."
}

$PHP = "D:\xampp\php\php.exe"
if (!(Test-Path $PHP)) {
    throw "XAMPP PHP was not found at $PHP"
}

$Service = Join-Path $Backend "app\Services\AiAssistantService.php"
if (!(Test-Path $Service)) {
    throw "AiAssistantService.php not found: $Service"
}

$Existing = [System.IO.File]::ReadAllText($Service, [System.Text.Encoding]::UTF8)

if ($Existing -match "private function practiceProblemsResponse" -and
    $Existing -match "codeforge:copilot:decision") {
    Write-Host "[INFO] PATCH 005 appears to be already installed."
    exit 0
}

if ($Existing -notmatch "private function askGroqModel" -or
    $Existing -notmatch "openai/gpt-oss-120b" -or
    $Existing -notmatch "private function buildModelMessages") {
    throw "Current AiAssistantService.php does not match the Groq PATCH-004 service. No files were changed."
}

$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = "$Service.backup-reliability005-$Stamp"

try {
    Copy-Item $Service $Backup -Force
    Write-Host "[BACKUP] $Backup"

    [System.IO.File]::WriteAllBytes(
        $Service,
        [Convert]::FromBase64String("")
    )

    Write-Host "[FIX] Added local topic problem recommendations"
    Write-Host "[FIX] Added 5-minute identical-request cache"
    Write-Host "[FIX] Reduced AI history payload to conserve Groq free-tier TPM"
    Write-Host "[FIX] Normal coaching now uses medium reasoning; coding/debugging keeps high reasoning"
    Write-Host "[FIX] Enabled strict Groq JSON schema output"
    Write-Host "[FIX] Tightened prompt against unsupported reminders/actions"

    & $PHP -l $Service
    if ($LASTEXITCODE -ne 0) {
        throw "PHP syntax validation failed."
    }

    Push-Location $Backend
    try {
        & $PHP artisan optimize:clear
        if ($LASTEXITCODE -ne 0) {
            throw "artisan optimize:clear failed."
        }
        & $PHP artisan cache:clear
        if ($LASTEXITCODE -ne 0) {
            throw "artisan cache:clear failed."
        }
    }
    finally {
        Pop-Location
    }

    Write-Host ""
    Write-Host "[SUCCESS] PATCH 005 installed."
    Write-Host ""
    Write-Host "Restart backend:"
    Write-Host "D:\xampp\php\php.exe artisan serve --host=127.0.0.1 --port=8000"
    Write-Host ""
    Write-Host "Recommended tests:"
    Write-Host "  Give me a list of Math problems"
    Write-Host "  give me some math problems to practice"
    Write-Host "  What should I practice?"
    Write-Host "  Tell me how to improve my skills over the next two weeks."
    Write-Host "  Analyze this C++ code and find the TLE cause: ..."
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    if (Test-Path $Backup) {
        Copy-Item $Backup $Service -Force
        Write-Host "[ROLLBACK] Restored $Backup"
    }
    exit 1
}
